    # Use a 4D DP table to store the maximum value collected by two paths
    # dp[i1][j1][i2] represents the maximum value collected when one path is at (i1, j1)
    # and the other path is at (i2, j2) where j2 = i1 + j1 - i2
    dp = [[[-1] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)]
    dp[0][0][0] = grid[0][0]

    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(N):
                j2 = i1 + j1 - i2
                if j2 < 0 or j2 >= N or grid[i1][j1] == 0 or grid[i2][j2] == 0:
