                    for di2, dj2 in [(-1, 0), (0, -1)]:
                        pi1, pj1 = i1 + di1, j1 + dj1
                        pi2, pj2 = i2 + di2, j2 + dj2
                        if 0 <= pi1 < N and 0 <= pj1 < N and 0 <= pi2 < N and 0 <= pj2 < N:
                            if dp[pi1][pj1][pi2] != -1:
                                value = dp[pi1][pj1][pi2]
                                if (i1, j1) == (i2, j2):
