    return max(0, dp[N - 1][N - 1][N - 1])

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    valid_combinations = []

    for a1 in range(1, 10):
        for a2 in range(1, 10):
            if a2 == a1:
                continue
            for a3 in range(1, 10):
                if a3 == a1 or a3 == a2:
                    continue
                num1 = 100 * a1 + 10 * a2 + a3
                num2 = 2 * num1
                num3 = 3 * num1

                b1, b2, b3 = num2 // 100, (num2 // 10) % 10, num2 % 10
                c1, c2, c3 = num3 // 100, (num3 // 10) % 10, num3 % 10

                digits = set([a1, a2, a3, b1, b2, b3, c1, c2, c3])
                if len(digits) == 9 and 1 <= num2 < 1000 and 1 <= num3 < 1000:
                    valid_combinations.append((num1, num2, num3))

    return sorted(valid_combinations)

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Finds the maximum product that can be obtained by inserting K multiplication signs into the number string.

    :param num_str: str - A string representing the number string.
    :param N: int - The length of the number string.
    :param K: int - The number of multiplication signs to insert.
    :return: int - The maximum product that can be obtained.
    """
    if not num_str or N <= 0 or K < 0 or K >= N:
        raise ValueError("Invalid input parameters.")

    def helper(start, end, k):
        if k == 0:
            return int(num_str[start:end+1])

        max_prod = 0
        for i in range(start, end - k + 1):
            left_part = int(num_str[start:i+1])
            right_part = helper(i + 1, end, k - 1)
            max_prod = max(max_prod, left_part * right_part)

        return max_prod

    return helper(0, N - 1, K)

